    if (!isset($icons[$name])) {
        return '';
    }

    $innerSvg = $icons[$name];
    $cssClass = 'dh-svg-icon dh-icon-' . sanitize_html_class($name) . ($classes ? ' ' . esc_attr($classes) : '');

    $hasAriaLabel = !empty($attributes['aria-label']);
    $ariaAttr = $hasAriaLabel
        ? 'role="img" aria-label="' . esc_attr($attributes['aria-label']) . '"'
        : 'aria-hidden="true"';

    $extraAttr = '';
    foreach ($attributes as $key => $val) {
        if ($key !== 'aria-label' && preg_match('/^[a-zA-Z0-9_\-]+$/', $key)) {
            $extraAttr .= ' ' . esc_attr($key) . '="' . esc_attr((string)$val) . '"';
        }
    }

    return sprintf(
        '<svg class="%s" width="%d" height="%d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" %s%s>%s</svg>',
        $cssClass,
        $size,
        $size,
        $ariaAttr,
        $extraAttr,
        $innerSvg
    );
}
